import sys

def find_relation(l, melody1, melody2):
    notes = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]

    # Check for Transposition
    def is_transposition(m1, m2):
        shift = None
        for i in range(1, l):
            diff = (notes.index(m2[i]) - notes.index(m1[i])) % 12
            if shift is None:
                shift = diff
            elif diff != shift:
                return False
        return True

    # Check for Retrograde
    def is_retrograde(m1, m2):
        return m1 == m2[::-1]

    # Check for Inversion
    def is_inversion(m1, m2):
        first_note_index = notes.index(m1[0])
        for i in range(1, l):
            original_diff = (notes.index(m1[i]) - first_note_index) % 12
            inverted_diff = (first_note_index - notes.index(m2[i])) % 12
            if original_diff != inverted_diff:
                return False
        return True

    if is_transposition(melody1, melody2):
        return "Transposition"
    elif is_retrograde(melody1, melody2):
        return "Retrograde"
    elif is_inversion(melody1, melody2):
        return "Inversion"
    else:
        return "Nonsense"

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    l = int(data[0])
    melody1 = data[1:l+1]
    melody2 = data[l+1:2*l+1]

    result = find_relation(l, melody1, melody2)
    print(result)

